use codex_protocol::models::ResponseItem;
use std::collections::HashSet;
use serde_json::json;
fn normalize_function_call_output_adjacency(input: Vec<ResponseItem>) -> Vec<ResponseItem> {
    let mut normalized = Vec::with_capacity(input.len());
    let mut pending_call_ids = HashSet::new();
    let mut deferred = Vec::new();

    for item in input {
        match &item {
            ResponseItem::FunctionCall { call_id, .. } => {
                pending_call_ids.insert(call_id.clone());
                normalized.push(item);
            }
            ResponseItem::FunctionCallOutput {
                call_id: Some(call_id),
                ..
            } if pending_call_ids.remove(call_id) => {
                normalized.push(item);
                if pending_call_ids.is_empty() {
                    normalized.append(&mut deferred);
                }
            }
            _ if !pending_call_ids.is_empty() => deferred.push(item),
            _ => normalized.push(item),
        }
    }
    normalized.append(&mut deferred);
    normalized
}

#[test]
fn strict_responses_pairing_moves_hook_context_after_function_output() {
    let input: Vec<ResponseItem> = vec![
        serde_json::from_value(json!({
            "type": "function_call",
            "name": "list_agents",
            "arguments": "{}",
            "call_id": "call-g4"
        }))
        .expect("function call"),
        serde_json::from_value(json!({
            "type": "message",
            "role": "developer",
            "content": [{"type": "input_text", "text": "AUTHORITY.REATTESTED"}]
        }))
        .expect("hook context"),
        serde_json::from_value(json!({
            "type": "function_call_output",
            "call_id": "call-g4",
            "output": "{\"agents\":[]}"
        }))
        .expect("function output"),
    ];

    let normalized = normalize_function_call_output_adjacency(input);
    let kinds = normalized
        .iter()
        .map(|item| serde_json::to_value(item).expect("serialize")["type"].clone())
        .collect::<Vec<_>>();

    assert_eq!(
        kinds,
        vec![
            json!("function_call"),
            json!("function_call_output"),
            json!("message"),
        ]
    );
}

#[test]
fn strict_responses_pairing_preserves_custom_output_and_hook_context() {
    let values = vec![
        json!({"type":"custom_tool_call","name":"apply_patch","call_id":"patch-1","input":"*** Begin Patch\n*** End Patch\n"}),
        json!({"type":"message","role":"developer","content":[{"type":"input_text","text":"AUTHORITY.REATTESTED"}]}),
        json!({"type":"message","role":"developer","content":[{"type":"input_text","text":"POST-MUTATION OBSERVATION"}]}),
        json!({"type":"custom_tool_call_output","call_id":"patch-1","output":"patch rejected: read-only sandbox"}),
    ];
    let input: Vec<ResponseItem> = values
        .into_iter()
        .map(|v| serde_json::from_value(v).unwrap())
        .collect();
    let expected = vec![
        input[0].clone(),
        input[3].clone(),
        input[1].clone(),
        input[2].clone(),
    ];
    let normalized = normalize_function_call_output_adjacency(input);
    assert_eq!(normalized, expected);
    assert_eq!(
        normalize_function_call_output_adjacency(normalized.clone()),
        normalized
    );
}

#[test]
fn strict_responses_pairing_keeps_mixed_batch_and_unmatched_output() {
    let values = vec![
        json!({"type":"function_call","name":"list_agents","call_id":"same-id","arguments":"{}"}),
        json!({"type":"custom_tool_call","name":"apply_patch","call_id":"same-id","input":"patch"}),
        json!({"type":"message","role":"developer","content":[{"type":"input_text","text":"hook"}]}),
        json!({"type":"custom_tool_call_output","call_id":"same-id","output":"denied"}),
        json!({"type":"function_call_output","call_id":"other-id","output":"unmatched"}),
        json!({"type":"function_call_output","call_id":"same-id","output":"{}"}),
    ];
    let input: Vec<ResponseItem> = values
        .into_iter()
        .map(|v| serde_json::from_value(v).unwrap())
        .collect();
    let expected = vec![
        input[0].clone(),
        input[1].clone(),
        input[3].clone(),
        input[5].clone(),
        input[2].clone(),
        input[4].clone(),
    ];
    assert_eq!(normalize_function_call_output_adjacency(input), expected);
}

